// message_catalog.rs is generated by build.rs from the `ctr!` calls of `src/`
// and the `.po` files of `i18n/`.
include!(concat!(env!("OUT_DIR"), "/message_catalog.rs"));

/// Translates a message with a disambiguation context (the `msgctxt` of a `.po`
/// file) into the language that Slint has selected, and puts the arguments into
/// it.
///
/// The build script writes a catalog entry for each call, so a call with no
/// entry does not compile. On a thread with no Slint context, such as a worker
/// thread, the result is the source text.
///
/// # Forms
///
/// ```ignore
/// ctr!("MenuBar", "File")
/// ctr!("MenuBar", "Open {}", name)
/// ctr!("MenuBar", "One file", "{n} files", count)
/// ctr!("MenuBar", "One {} file", "{n} {} files", count, kind)
/// ```
///
/// # xgettext
///
/// ```sh
/// xgettext -L Rust --keyword='ctr!:1c,2' \
///     --keyword='ctr!:1c,2,3,4t' --keyword='ctr!:1c,2,3,5t' ... \
///     --keyword='ctr!:1c,2,3,10t' ...
/// ```
macro_rules! ctr {
    // Plural, with or without format arguments.
    ($ctx:literal, $singular:literal, $plural:literal, $n:expr $(, $arg:expr)* $(,)?) => {{
        const MESSAGE: &$crate::i18n::PluralMessage =
            match $crate::i18n::plural_message($ctx, $singular, $plural) {
                Some(message) => message,
                None => panic!(
                    "{}",
                    concat!(
                        "no catalog entry for ctr!(",
                        stringify!($ctx),
                        ", ",
                        stringify!($singular),
                        ", ",
                        stringify!($plural),
                        ", ..)"
                    )
                ),
            };
        let args: &[slint::SharedString] = &[
            $( slint::SharedString::from(std::format!("{}", $arg)) ),*
        ];
        slint::private_unstable_api::re_exports::translate_from_bundle_with_plural(
            MESSAGE.translations,
            $crate::i18n::PLURAL_RULES,
            args,
            $n as i32,
        )
    }};
    // Singular, with or without format arguments.
    ($ctx:literal, $msgid:literal $(, $arg:expr)* $(,)?) => {{
        const MESSAGE: &$crate::i18n::Message = match $crate::i18n::message($ctx, $msgid) {
            Some(message) => message,
            None => panic!(
                "{}",
                concat!(
                    "no catalog entry for ctr!(",
                    stringify!($ctx),
                    ", ",
                    stringify!($msgid),
                    ", ..)"
                )
            ),
        };
        let args: &[slint::SharedString] = &[
            $( slint::SharedString::from(std::format!("{}", $arg)) ),*
        ];
        slint::private_unstable_api::re_exports::translate_from_bundle(MESSAGE.translations, args)
    }};
}

pub(crate) use ctr;

#[cfg(test)]
mod i18n_tests {
    use slint::{SelectBundledTranslationError, select_bundled_translation};

    use super::*;
    use crate::slint_ui::ErrorDialog;
    use crate::test_support::slint_thread::on_fresh_slint_thread;

    fn new_dialog() -> ErrorDialog {
        ErrorDialog::new().expect("the headless platform creates components")
    }

    /// The texts of 2 calls that the `.po` files translate.
    fn texts() -> (String, String) {
        (
            ctr!("FileDialog", "OBJ files").to_string(),
            ctr!("ErrorDialog", "File: {}", "part.stl").to_string(),
        )
    }

    /// The texts of [`texts`] on a fresh Slint thread, with a component and
    /// `language` selected.
    fn texts_in(language: &'static str) -> (String, String) {
        on_fresh_slint_thread(move || {
            let _dialog = new_dialog();
            select_bundled_translation(language).expect("bundled language");
            texts()
        })
    }

    fn source_texts() -> (String, String) {
        ("OBJ files".to_owned(), "File: part.stl".to_owned())
    }

    #[test]
    fn a_selected_language_translates_the_rust_texts() {
        let (spanish_filter, spanish_file) = texts_in("es");
        let (german_filter, german_file) = texts_in("de");
        assert_ne!(spanish_filter, "OBJ files");
        assert_ne!(spanish_file, "File: part.stl");
        assert!(spanish_file.contains("part.stl"), "{spanish_file}");
        assert_ne!(german_filter, "OBJ files");
        assert_ne!(german_file, "File: part.stl");
        assert_ne!(german_filter, spanish_filter);
        assert_ne!(german_file, spanish_file);
    }

    #[test]
    fn english_gives_the_source_texts() {
        let texts = on_fresh_slint_thread(|| {
            let _dialog = new_dialog();
            select_bundled_translation("es").expect("bundled language");
            select_bundled_translation("en").expect("the source language");
            texts()
        });
        assert_eq!(texts, source_texts());
    }

    #[test]
    fn a_thread_without_slint_gives_the_source_texts() {
        let texts = std::thread::spawn(texts).join().expect("the thread ends");
        assert_eq!(texts, source_texts());
    }

    #[test]
    fn the_catalog_has_the_languages_of_slints_bundle_in_their_order() {
        let bundled = on_fresh_slint_thread(|| {
            let _dialog = new_dialog();
            match select_bundled_translation("not-a-language") {
                Err(SelectBundledTranslationError::LanguageNotFound {
                    available_languages,
                }) => available_languages
                    .iter()
                    .map(ToString::to_string)
                    .collect::<Vec<_>>(),
                other => panic!("expected an unknown language, got {other:?}"),
            }
        });
        assert_eq!(bundled, LANGUAGES);
    }
}
